/* Cybersecurity — L4 Difesa operativa e analisi: 6 lezioni approfondite (taglio difensivo / blue team). */
(function (ST) {
  'use strict';
  const C = ST.content, { mc, fill, order } = C;

  /* ---------- 1 · Log e SIEM ---------- */
  C.addTopic({
    id: 'cyb-log-e-siem', subject: 'cyb', stage: 'L4', minutes: 12,
    title: 'Log, SIEM e correlazione degli eventi',
    summary: 'Cosa registrare, come normalizzare e sincronizzare i log, come un SIEM correla gli eventi e come leggere estratti di log.',
    objectives: ['Scegliere le fonti di log e i campi essenziali da raccogliere', 'Spiegare normalizzazione, sincronizzazione oraria in UTC, conservazione e correlazione', 'Leggere estratti di log di autenticazione e web server contando gli eventi in modo esatto'],
    pages: [
      { h: 'Perché si registra', b: `Un **log** è la traccia scritta di un evento: chi ha fatto cosa, su quale sistema, quando e con quale esito. Senza log un incidente non si può né rilevare né ricostruire: si resta ciechi.\n\nUn buon evento risponde a sei domande:\n\n- **Quando** (data, ora, fuso orario);\n- **Chi** (utente, account di servizio, indirizzo IP di origine);\n- **Cosa** (azione: login, lettura file, avvio processo);\n- **Dove** (host, applicazione, risorsa);\n- **Esito** (riuscito o fallito);\n- **Da dove** (origine di rete o sessione).\n\nNon si registra tutto: troppo rumore costa spazio, denaro e attenzione. Si parte dagli **eventi di sicurezza** utili: autenticazioni riuscite e fallite, cambi di privilegio, creazione di account, modifiche alla configurazione, accessi a dati sensibili, avvio di processi, connessioni di rete anomale.\n\n> Regola pratica: registra ciò che ti servirebbe sapere **dopo** un incidente per rispondere a «cosa è successo e da dove è cominciato?».` },
      { h: 'Le fonti di log', b: `I log nascono in punti diversi, e ciascuno vede una parte della storia.\n\n- **Sistemi operativi**: eventi di accesso, servizi, errori (per esempio il registro di sicurezza di Windows, auth.log e journal su Linux).\n- **Endpoint (EDR)**: processi avviati, albero padre-figlio, file e connessioni.\n- **Rete**: firewall, proxy, DNS, VPN, sistemi di rilevamento intrusioni, flussi NetFlow.\n- **Identità**: directory (per esempio Active Directory), provider SSO, autenticazione a più fattori.\n- **Applicazioni e web server**: richieste HTTP, errori, azioni degli utenti.\n- **Cloud e SaaS**: log di audit delle API e delle console amministrative.\n\nIl valore sta nell’**incrocio**: un login VPN da un paese inusuale, seguito da un accesso a un file server e da un grosso trasferimento in uscita, racconta una storia che nessuna fonte da sola racconta.\n\nAttenzione ai **punti ciechi**: un sistema che non invia log è un sistema invisibile. Un inventario delle fonti, con la loro copertura, fa parte della difesa.` },
      { h: 'Normalizzazione e sincronizzazione oraria', b: `Fonti diverse scrivono formati diversi (testo libero, JSON, syslog, XML) e chiamano lo stesso concetto con nomi diversi. La **normalizzazione** converte i campi in uno schema comune, così una regola scritta una volta funziona su tutte le fonti.\n\n> Firewall: src=203.0.113.50 → campo comune **source.ip**\n> Web server: client "203.0.113.50" → campo comune **source.ip**\n\nIl **parsing** estrae i campi dal testo; l’**arricchimento** aggiunge contesto (geolocalizzazione, reparto dell’utente, criticità dell’host).\n\nIl **tempo** è il campo più delicato. Se due server hanno orologi sfasati la sequenza degli eventi si inverte e la ricostruzione è sbagliata. Per questo si usa **NTP** e si registra in **UTC**, convertendo in ora locale solo in visualizzazione. Ogni orario deve indicare il fuso (per esempio 2026-10-14T10:05:00Z, dove Z = UTC).\n\n> Esempio: server A segna 10:04, server B (in anticipo di 5 minuti) segna 10:07. In UTC reale B ha registrato alle 10:02, **prima** di A.` },
      { h: 'Conservazione, integrità e privacy', b: `Quanto a lungo tenere i log? La **retention** dipende da tre fattori: esigenze investigative, obblighi normativi e costo di archiviazione.\n\n- Ricerca rapida: pochi mesi su storage veloce (**hot**).\n- Archivio più lento ed economico (**cold**) per un tempo più lungo.\n- Gli attacchi mirati possono restare nascosti a lungo: una conservazione troppo breve impedisce di capire quando è iniziata una compromissione.\n\nI log vanno protetti:\n\n- inviali **subito a un server remoto** (log forwarding): se un intruso cancella i log locali, la copia resta;\n- limita chi può modificarli o cancellarli (separazione dei ruoli);\n- proteggili con firme o hash e con archiviazione in sola aggiunta (**append-only**).\n\nI log contengono **dati personali** (utenti, IP): si applicano minimizzazione, controllo degli accessi e tempi di conservazione proporzionati (GDPR). Non vanno mai registrati in chiaro **password** o dati di pagamento completi.` },
      { h: 'Che cos’è un SIEM', b: `Un **SIEM** (Security Information and Event Management) raccoglie i log da molte fonti in un punto, li normalizza, li conserva, permette di cercarli e genera **allarmi**.\n\nLe funzioni principali:\n\n1. **Raccolta** (agenti, syslog, API, connettori);\n2. **Normalizzazione e arricchimento**;\n3. **Archiviazione e ricerca**;\n4. **Correlazione** tra eventi diversi;\n5. **Allerta e dashboard**;\n6. **Gestione dei casi** (triage, indagine, chiusura).\n\nIl percorso tipico di un evento: generazione → raccolta → normalizzazione → correlazione → allarme → **triage** dell’analista → eventuale incidente.\n\nIl SIEM non è magia: restituisce solo ciò che vi si è inviato e ciò che le regole sanno cercare. Un SIEM con poche fonti o con regole non mantenute dà un’illusione di sicurezza. Strumenti affini: **SOAR** (automazione delle risposte) e **XDR** (rilevamento esteso a endpoint, rete e cloud).` },
      { h: 'Regole di correlazione e alert fatigue', b: `Una **regola di correlazione** collega più eventi in una condizione significativa. Un singolo login fallito è normale; una sequenza no.\n\n> **Regola**: 5 o più login falliti dallo stesso IP in 60 secondi, **seguiti** da un login riuscito dallo stesso IP → allarme «possibile password indovinata».\n> **Regola**: login riuscito da un paese mai visto per quell’utente entro un’ora da un login nel paese abituale → allarme «viaggio impossibile».\n\nOgni regola ha **soglia** (quanti eventi), **finestra** (in quanto tempo) e **raggruppamento** (per IP, per utente, per host).\n\nSe le regole generano troppi falsi allarmi nasce l’**alert fatigue**: gli analisti, sommersi, ignorano o chiudono in fretta anche gli allarmi veri. Contromisure:\n\n- tarare soglie e whitelist documentate per i comportamenti noti e legittimi;\n- assegnare **priorità** in base alla criticità dell’asset;\n- misurare la qualità di ogni regola (quanti allarmi sono veri) e spegnere o riscrivere quelle inutili.\n\nÈ meglio avere poche regole affidabili che mille regole ignorate.` },
      { h: 'Leggere un log di autenticazione', b: `Leggere un log significa individuare **pattern**: chi, da dove, quante volte, in quanto tempo, con quale esito. Esempio (indirizzi di documentazione):\n\n> 03:12:01 sshd: Failed password for root from 203.0.113.50\n> 03:12:03 sshd: Failed password for root from 203.0.113.50\n> 03:12:05 sshd: Failed password for admin from 203.0.113.50\n> 03:12:08 sshd: Failed password for admin from 203.0.113.50\n> 03:12:11 sshd: Failed password for deploy from 203.0.113.50\n> 03:12:14 sshd: Accepted password for deploy from 203.0.113.50\n> 03:12:20 sshd: Failed password for mrossi from 198.51.100.7\n\n**Conteggi**: 7 righe; **6** fallimenti in totale e 1 accesso riuscito. Da 203.0.113.50 arrivano **5** fallimenti e poi un successo, su **3** utenti diversi (root, admin, deploy), in **13** secondi (dalle 03:12:01 alle 03:12:14).\n\n**Interpretazione**: pochi secondi, più nomi utente e un successo finale sull’ultimo indicano un tentativo automatico di indovinare password che è andato a segno su deploy. Il fallimento isolato di mrossi (altro IP) è probabilmente un errore umano. **Azione**: verificare l’account deploy, forzare il reset, bloccare l’IP, cercare cosa ha fatto la sessione dopo le 03:12:14.` },
      { h: 'Leggere un log di un web server', b: `Il formato «combined» dei web server riporta IP, orario, richiesta, **codice di stato** e dimensione. Codici utili: **200** ok, **302** reindirizzamento, **403** vietato, **404** non trovato.\n\n> 198.51.100.20 [10:01:02] "GET /index.html" 200\n> 198.51.100.20 [10:01:03] "GET /login" 200\n> 203.0.113.9 [10:02:10] "GET /admin" 403\n> 203.0.113.9 [10:02:11] "GET /backup.zip" 404\n> 203.0.113.9 [10:02:12] "GET /.git/config" 404\n> 203.0.113.9 [10:02:13] "GET /wp-login.php" 404\n> 198.51.100.20 [10:02:30] "POST /login" 302\n\n**Conteggi**: 7 richieste; **4** dall’IP 203.0.113.9, tutte in **3** secondi (10:02:10–10:02:13); **3** risposte 404, **1** risposta 403, **2** risposte 200.\n\n**Interpretazione**: il visitatore 198.51.100.20 ha un comportamento normale (pagina, login, POST con redirect). L’IP 203.0.113.9 prova percorsi tipici di una scansione (area admin, backup, repository, pannello di un CMS) ottenendo quasi solo 404: è **ricognizione automatica**. Nessun successo, quindi nessuna esposizione, ma è utile bloccare o limitare la frequenza e controllare che quei file non esistano davvero.` }
    ],
    exercises: [
      mc('Perché si registrano gli eventi in UTC?', ['Per confrontare in modo coerente eventi di sistemi in fusi orari diversi', 'Perché UTC riduce lo spazio occupato dai log', 'Perché l’ora locale è vietata dal GDPR', 'Perché UTC rende i log cifrati'], 0, 'Un’unica scala oraria evita confusioni su fusi e ora legale e rende affidabile la sequenza.'),
      fill('Quanti login falliti ci sono?\n10:15:01 Failed password for bianchi from 192.0.2.10\n10:15:04 Failed password for bianchi from 192.0.2.10\n10:15:09 Failed password for bianchi from 192.0.2.10\n10:15:30 Accepted password for bianchi from 192.0.2.10\n10:16:00 Failed password for admin from 192.0.2.99', ['4', 'quattro'], 'Le righe Failed sono 4: tre per bianchi e una per admin; una sola è Accepted.'),
      fill('Nell’estratto dell’autenticazione della lezione, quanti secondi passano tra il primo fallimento (03:12:01) e l’accesso riuscito (03:12:14)?', ['13', 'tredici'], '14 − 1 = 13 secondi.'),
      fill('Nell’estratto del web server della lezione, quante richieste hanno avuto risposta 404?', ['3', 'tre'], 'Backup.zip, .git/config e wp-login.php: tre risposte 404.'),
      mc('Server A segna un evento alle 10:04. Server B, con l’orologio in anticipo di 5 minuti, segna un altro evento alle 10:07. Quale è avvenuto prima?', ['Quello di B, alle 10:02 reali', 'Quello di A, perché 10:04 è minore di 10:07', 'Sono simultanei', 'Non si può dire in nessun caso'], 0, 'Correggendo lo sfasamento B diventa 10:02: precede A di due minuti. Da qui l’importanza di NTP.'),
      order('Ordina il percorso di un evento nel SIEM', ['Generazione', 'Raccolta', 'Normalizzazione', 'Correlazione', 'Allarme', 'Triage'], 'Dall’evento grezzo all’analista: generazione, raccolta, normalizzazione, correlazione, allarme, triage.'),
      order('Ordina cronologicamente gli eventi (convertiti in UTC)', ['Alert 12:05 +02:00', 'Upload 10:30 UTC', 'Logout 09:50 -01:00', 'Login 11:58 +01:00'], 'In UTC: Alert 10:05, Upload 10:30, Logout 10:50 (09:50 + 1 h), Login 10:58 (11:58 − 1 h).'),
      mc('Quale regola è una vera correlazione?', ['5 login falliti in 60 secondi dallo stesso IP seguiti da un login riuscito', 'Un singolo login fallito', 'L’avvio del server', 'Il riempimento del disco al 50%'], 0, 'La correlazione unisce più eventi con soglia, finestra e raggruppamento.'),
      mc('Qual è la contromisura più efficace all’alert fatigue?', ['Tarare e misurare le regole, dando priorità agli asset critici', 'Aumentare il numero di regole', 'Ignorare gli allarmi notturni', 'Disattivare tutti gli allarmi a priorità alta'], 0, 'Meno allarmi, ma più affidabili, ridanno attenzione agli analisti.'),
      mc('Perché inviare i log a un server remoto subito dopo la generazione?', ['Se l’intruso cancella i log locali esiste ancora una copia', 'Per risparmiare banda', 'Per rendere i log più brevi', 'Perché i file locali non sono leggibili'], 0, 'I log locali sono il primo obiettivo di chi vuole nascondere le tracce.')
    ],
    test: [
      mc('Una voce di log non dovrebbe mai contenere in chiaro:', ['Password o dati di pagamento completi', 'L’orario', 'Il nome host', 'Il codice di stato HTTP'], 0, 'Registrare segreti trasforma i log in un bersaglio: vanno mascherati.'),
      fill('Qual è il codice di stato HTTP «risorsa non trovata»? (numero)', ['404'], '404 = Not Found.'),
      fill('Quanti login riusciti ci sono?\n09:01:10 Accepted password for rossi from 192.0.2.5\n09:02:44 Failed password for verdi from 192.0.2.8\n09:03:00 Accepted publickey for verdi from 192.0.2.8\n09:05:12 Failed password for root from 192.0.2.77', ['2', 'due'], 'Sono Accepted le righe 09:01:10 e 09:03:00.'),
      mc('Nell’estratto precedente, quale utente ha un fallimento seguito da un accesso riuscito dallo stesso IP?', ['verdi', 'rossi', 'root', 'nessuno'], 0, 'verdi: Failed alle 09:02:44, Accepted alle 09:03:00, entrambi da 192.0.2.8.'),
      mc('Che cosa fa la normalizzazione?', ['Porta campi di fonti diverse in uno schema comune', 'Cancella i log vecchi', 'Cifra i log', 'Aumenta la frequenza di campionamento'], 0, 'Permette una regola unica valida per più fonti.'),
      mc('Quale elemento di una regola di correlazione dice «in quanto tempo»?', ['La finestra temporale', 'La soglia di eventi', 'Il raggruppamento per campo', 'La priorità assegnata'], 0, 'Soglia = quanti; finestra = in quanto tempo; raggruppamento = per quale chiave.'),
      mc('Quale scelta riduce il rischio che un attaccante nasconda le tracce?', ['Inoltro remoto con archiviazione append-only', 'Tenere i log solo sul server compromesso', 'Eliminare i log più vecchi di un giorno', 'Dare a tutti il permesso di scrittura sui log'], 0, 'Copia remota non modificabile: la prova resta anche se l’host è compromesso.'),
      fill('Nell’estratto del web server della lezione, da quanti IP diversi provengono le 7 richieste?', ['2', 'due'], 'Sono 198.51.100.20 e 203.0.113.9.')
    ]
  });

  /* ---------- 2 · Rilevamento e threat hunting ---------- */
  C.addTopic({
    id: 'cyb-rilevamento-e-threat-hunting', subject: 'cyb', stage: 'L4', minutes: 12, prereq: ['cyb-log-e-siem'],
    title: 'Rilevamento, falsi positivi e threat hunting',
    summary: 'Firme, comportamenti e anomalie; precision e recall con numeri; regole in stile Sigma; caccia alle minacce, baseline e trappole.',
    objectives: ['Distinguere rilevamento basato su firme, comportamento e anomalie', 'Calcolare precision, recall e falsi positivi da un caso numerico', 'Descrivere un ciclo di threat hunting guidato da ipotesi e il ruolo di honeypot e canary token'],
    pages: [
      { h: 'Detection engineering', b: `Il **detection engineering** tratta il rilevamento come un prodotto di ingegneria: ogni regola ha un obiettivo, dati di ingresso, test, manutenzione e un responsabile.\n\nCiclo di vita di una regola:\n\n1. **Requisito**: quale comportamento ostile voglio vedere (da intelligence, incidenti passati, red team)?\n2. **Dati**: la fonte di log necessaria esiste ed è completa?\n3. **Scrittura** e **test** su dati storici e su attività simulata e autorizzata;\n4. **Messa in produzione** con priorità e istruzioni per l’analista;\n5. **Misura e taratura**: quanti allarmi, quanti veri;\n6. **Ritiro** quando non serve più.\n\nUna regola senza test è un’ipotesi. Una regola senza **runbook** (cosa fare quando scatta) produce allarmi che nessuno sa gestire. Si tiene la regola in un repository con versioni, come il codice.` },
      { h: 'Firme, comportamento, anomalie', b: `Tre approcci complementari.\n\n- **Firme (signature)**: si cerca qualcosa di noto, come un hash, un indirizzo IP o una stringa. Sono precise e veloci, ma vedono solo ciò che già si conosce: un piccolo cambiamento le aggira.\n- **Comportamento**: si descrive *cosa fa* l’attore, non *come si chiama*. Esempio: un documento Office che avvia una shell dei comandi. Resiste ai cambi di strumento, richiede più contesto e può dare falsi allarmi.\n- **Anomalia**: si misura lo scostamento da una **baseline**, cioè dal normale. Può trovare minacce nuove, ma segnala anche eventi insoliti e innocui (una trasferta, un picco di fine mese).\n\n> Firma: l’hash del file è noto come malevolo → allarme.\n> Comportamento: winword.exe avvia powershell.exe → allarme.\n> Anomalia: l’utente scarica 30 GB contro una media di 200 MB → allarme.\n\nUna difesa solida combina i tre livelli: le firme scartano il rumore noto, i comportamenti coprono le tecniche, le anomalie sono la rete di sicurezza.` },
      { h: 'Falsi positivi e falsi negativi', b: `Ogni rilevamento può sbagliare in due modi.\n\n- **Falso positivo (FP)**: allarme su attività legittima. Costa tempo e alimenta l’alert fatigue.\n- **Falso negativo (FN)**: attività ostile non rilevata. Costa un incidente non visto.\n- **Vero positivo (VP)**: allarme corretto. **Vero negativo (VN)**: silenzio corretto.\n\nDue misure:\n\n- **Precision** = VP / (VP + FP): quanti allarmi sono veri;\n- **Recall** (sensibilità) = VP / (VP + FN): quante minacce reali trovo.\n\nCaso: una regola produce 200 allarmi, dei quali 150 veri; in realtà gli eventi ostili erano 250.\n\n> VP = 150, FP = 200 − 150 = 50, FN = 250 − 150 = 100\n> Precision = 150 / 200 = **75%**\n> Recall = 150 / 250 = **60%**\n\nUna regola molto sensibile aumenta la recall ma spesso peggiora la precision. Non esiste un valore perfetto: si decide in base al **rischio** (un asset critico tollera più falsi positivi).` },
      { h: 'Il problema della frequenza di base', b: `Quando le minacce sono rare, anche un buon rilevatore produce soprattutto falsi allarmi. Questo è l’effetto della **base rate**.\n\nCaso: 10 000 login in un giorno, 20 dei quali ostili (0,2%). Un modello rileva **16** dei 20 attacchi, ma segnala anche **84** login legittimi.\n\n> Allarmi totali = 16 + 84 = 100\n> Precision = 16 / 100 = **16%**\n> Recall = 16 / 20 = **80%**\n> Login legittimi = 10 000 − 20 = 9 980 → tasso di falsi positivi = 84 / 9 980 ≈ **0,84%**\n\nUn tasso di falsi positivi inferiore all’1% sembra ottimo, ma l’analista vede che **solo un allarme su sei circa è reale** (16 su 100).\n\nLezione: la precision dipende dalla rarità dell’evento. Per questo il rilevamento di eventi rari richiede **arricchimento** (contesto sull’utente e sull’asset), **priorità** e regole più specifiche, non solo soglie più basse.` },
      { h: 'Regole in stile Sigma', b: `**Sigma** è un formato aperto e indipendente dal prodotto per descrivere regole di rilevamento su log. Una regola Sigma si può poi **tradurre** nel linguaggio di query del SIEM in uso.\n\nStruttura tipica (semplificata):\n\n> title: Applicazione Office che avvia una shell dei comandi\n> logsource: categoria process_creation, prodotto windows\n> detection:\n>   selection: processo padre = winword.exe o excel.exe; processo figlio = powershell.exe o cmd.exe\n>   condition: selection\n> falsepositives: macro aziendali legittime documentate\n> level: medium\n\nElementi chiave: **logsource** (dove cercare), **detection** (cosa cercare e come combinare i criteri), **falsepositives** (casi legittimi attesi) e **level** (gravità).\n\nVantaggi: regole **portabili**, condivisibili tra team e comunità, leggibili. Limiti: una regola Sigma funziona solo se il log necessario viene davvero raccolto e se i campi sono normalizzati. Una regola senza i dati sottostanti è **inerte**.` },
      { h: 'Threat hunting', b: `Il **threat hunting** è la ricerca **proattiva** di attività ostili che le regole non hanno segnalato. Parte dall’assunzione «qualcuno potrebbe essere già dentro».\n\nUn ciclo guidato da **ipotesi**:\n\n1. **Ipotesi**: «un attore potrebbe usare un account di servizio per spostarsi lateralmente di notte»;\n2. **Dati**: quali log servono (autenticazioni, processi, rete)?\n3. **Analisi**: ricerche, aggregazioni, confronto con la baseline;\n4. **Esito**: trovato (si apre un incidente), non trovato (la copertura è confermata) o dati insufficienti;\n5. **Miglioramento**: ciò che si impara diventa una **nuova regola** di rilevamento o una correzione della raccolta log.\n\nEsempio di log da leggere:\n\n> 14:02:11 parent=explorer.exe child=chrome.exe\n> 14:02:40 parent=winword.exe child=powershell.exe\n> 14:03:02 parent=powershell.exe child=whoami.exe\n> 14:03:05 parent=powershell.exe child=net.exe\n\nLa catena winword → powershell → whoami e net è **anomala** (un documento non dovrebbe avviare una shell): i processi discendenti da winword sono **3**. Chrome da explorer è normale.` },
      { h: 'Baseline e anomalie numeriche', b: `Una **baseline** descrive il comportamento normale: login per ora, volume di dati in uscita, orari di lavoro, host contattati. Senza baseline «anomalo» è un’opinione.\n\nUn metodo semplice: media e **deviazione standard**; si misura quante deviazioni separano un valore dalla media (**z-score**).\n\n> Media: 40 login all’ora, deviazione standard: 5.\n> Osservati 70 login → z = (70 − 40) / 5 = **6**\n\nValori oltre 3 sono molto rari in condizioni normali: vale la pena indagare. Ma attenzione:\n\n- la baseline deve tenere conto di **stagionalità** (giorni feriali, fine mese);\n- un attaccante paziente può restare **sotto soglia** e «adattare» la baseline;\n- un cambiamento legittimo (nuova sede, nuova applicazione) provoca falsi positivi.\n\nLa baseline si aggiorna e si tara per gruppi omogenei (per ruolo, per tipo di server), non su tutta l’azienda insieme. Un’anomalia è un **indizio**, non una prova: serve sempre una verifica con altri dati.` },
      { h: 'Honeypot e canary token', b: `Gli strumenti di **inganno difensivo** sfruttano un fatto: nessun utente legittimo ha motivo di toccarli. Qualunque interazione è quindi sospetta, con pochissimi falsi positivi.\n\n- **Honeypot**: sistema esca che simula un servizio reale, isolato dalla rete di produzione. Registra chi lo contatta e come.\n- **Honeytoken / canary token**: dato esca, per esempio un file «Stipendi_2026.xlsx» in una cartella, un account fittizio, una chiave API inesistente o un record nel database. Quando viene letto, usato o aperto, genera un **allarme**.\n\n> Allarme: l’account «svc-backup2» (mai usato da nessuno) ha tentato un login dalla postazione PC-114.\n\nSignificato: PC-114 sta cercando credenziali o account da sfruttare, forse compromesso; si isola e si indaga.\n\nBuone pratiche: esche **credibili** ma isolate, mai collegate a sistemi reali; allarmi con alta priorità e responsabile chiaro; nessuna esca che possa danneggiare terzi. Gli inganni **non sostituiscono** le altre difese: sono un sensore a basso rumore per chi è già dentro.` }
    ],
    exercises: [
      fill('Una regola produce 200 allarmi, 150 dei quali veri. Qual è la precision in percentuale? (solo numero)', ['75', '75%'], 'Precision = VP / (VP + FP) = 150 / 200 = 75%.'),
      fill('Nello stesso caso gli eventi ostili reali erano 250. Qual è la recall in percentuale? (solo numero)', ['60', '60%'], 'Recall = 150 / 250 = 60%.'),
      fill('Sempre nello stesso caso, quanti sono i falsi negativi?', ['100', 'cento'], 'FN = 250 − 150 = 100: attività ostile non rilevata.'),
      mc('Quale approccio resiste meglio al cambio del nome del file o dell’hash di uno strumento ostile?', ['Il rilevamento basato su comportamento', 'La firma basata sull’hash del file', 'La firma basata sull’indirizzo IP noto', 'L’elenco dei nomi di file già visti'], 0, 'Descrive ciò che l’attore fa (tecnica), non l’identificativo dello strumento.'),
      fill('Nell’estratto di processi della lezione, quanti processi discendono (direttamente o no) da winword.exe?', ['3', 'tre'], 'powershell.exe, whoami.exe e net.exe.'),
      fill('Media 40 login/ora, deviazione standard 5. Con 70 login/ora quanto vale lo z-score?', ['6', 'sei'], '(70 − 40) / 5 = 6.'),
      order('Ordina il ciclo di threat hunting', ['Ipotesi', 'Dati', 'Analisi', 'Esito', 'Nuova regola'], 'Si parte dall’ipotesi, si individuano i dati, si analizza, si registra l’esito e si trasforma il risultato in rilevamento.'),
      mc('Perché un canary token ha pochissimi falsi positivi?', ['Nessun utente legittimo ha motivo di usarlo', 'Perché viene cifrato con una chiave forte', 'Perché i suoi allarmi sono confrontati con il SIEM', 'Perché registra solo gli accessi da rete esterna'], 0, 'Ogni interazione con un’esca è per definizione fuori dal normale.'),
      mc('Che cosa indica il campo falsepositives in una regola in stile Sigma?', ['I casi legittimi attesi che potrebbero far scattare la regola', 'Il numero di falsi allarmi già registrati dalla regola finora', 'Il livello di priorità che la regola assegna a ogni allarme', 'Le fonti di log da cui la regola esclude gli eventi ostili'], 0, 'Aiuta l’analista a decidere in fretta e chi tara la regola a creare eccezioni.'),
      mc('Una regola ha recall alta e precision bassa. Che cosa comporta?', ['Trova quasi tutte le minacce, ma con molti falsi allarmi', 'Genera pochi allarmi, quasi tutti corretti ma incompleti', 'Non trova quasi nulla e non genera falsi allarmi', 'Trova ogni minaccia e non produce alcun falso allarme'], 0, 'Tutti gli attacchi quasi vengono visti, ma gli analisti devono scartare molto rumore.')
    ],
    test: [
      fill('Una regola produce 50 allarmi, 40 dei quali veri; gli eventi ostili reali erano 80. Quanto vale la recall in percentuale? (solo numero)', ['50', '50%'], 'Recall = 40 / 80 = 50%.'),
      fill('Nello stesso caso, qual è la precision in percentuale? (solo numero)', ['80', '80%'], 'Precision = 40 / 50 = 80%.'),
      mc('Che cos’è un falso negativo?', ['Attività ostile che non genera allarme', 'Un allarme generato da attività legittima', 'Un allarme corretto su attività ostile', 'Un log cancellato prima dell’analisi'], 0, 'È il caso più pericoloso: la minaccia passa inosservata.'),
      mc('Da che cosa parte una caccia alle minacce ben condotta?', ['Da un’ipotesi verificabile sui dati disponibili', 'Da un allarme critico appena generato dal SIEM', 'Da una scansione completa di tutti i file di rete', 'Dalla segnalazione generica di un fornitore esterno'], 0, 'L’ipotesi orienta la ricerca e rende misurabile l’esito.'),
      mc('Perché la baseline va calcolata per gruppi omogenei?', ['Perché ruoli e server diversi hanno comportamenti normali diversi', 'Perché i gruppi riducono il volume complessivo dei log raccolti e conservati', 'Perché le norme di settore vietano una baseline unica per tutti', 'Perché separare i gruppi azzera i falsi positivi di ogni regola'], 0, 'Un contabile e un amministratore di sistema hanno profili d’uso molto differenti.'),
      fill('Con 10 000 login, 20 ostili, 16 rilevati e 84 falsi allarmi: quanti sono gli allarmi totali?', ['100', 'cento'], '16 veri + 84 falsi = 100 allarmi.'),
      mc('Una firma basata su hash è debole perché:', ['Basta una minima modifica del file per cambiare l’hash', 'Il calcolo dell’hash è troppo lento per i controlli in produzione', 'Gli hash dei file non possono essere caricati nel SIEM aziendale', 'L’hash permette di identificare solo i file dei sistemi Linux'], 0, 'Cambia un bit e l’hash è completamente diverso: la firma non riconosce più il file.')
    ]
  });

  /* ---------- 3 · Incident response ---------- */
  C.addTopic({
    id: 'cyb-incident-response', subject: 'cyb', stage: 'L4', minutes: 12, prereq: ['cyb-rilevamento-e-threat-hunting'],
    title: 'Incident response: dal rilevamento alle lezioni apprese',
    summary: 'Il ciclo di vita della risposta agli incidenti, i ruoli, i playbook, la comunicazione, la conservazione delle prove e un tabletop su ransomware.',
    objectives: ['Elencare e distinguere le fasi del ciclo di vita della risposta agli incidenti', 'Spiegare ruoli, playbook, comunicazione e conservazione delle prove', 'Ordinare e misurare la linea temporale di un incidente ransomware simulato'],
    pages: [
      { h: 'Evento, incidente e ciclo di vita', b: `Un **evento** è qualsiasi occorrenza osservabile (un login, un allarme). Un **incidente** è un evento (o una serie) che compromette, o rischia di compromettere, riservatezza, integrità o disponibilità.\n\nIl modello più usato è quello del **NIST** (SP 800-61), articolato in sei passi pratici:\n\n1. **Preparazione**\n2. **Rilevamento e analisi**\n3. **Contenimento**\n4. **Eradicazione**\n5. **Recupero**\n6. **Lezioni apprese**\n\nIl NIST raggruppa 3, 4 e 5 in un’unica fase, ma separarle aiuta a ricordare lo scopo di ciascuna. Non è una sequenza rigida: durante l’analisi si torna spesso indietro (si scoprono altri host compromessi e si deve ripetere il contenimento). Il ciclo è una **spirale**: le lezioni apprese migliorano la preparazione dell’incidente successivo.\n\nL’obiettivo non è «fermare ogni attacco», ma **limitare il danno, ripristinare il servizio e imparare**.` },
      { h: 'Preparazione: ruoli, piani e playbook', b: `La fase più importante avviene **prima** dell’incidente. Ci si prepara con:\n\n- un **piano di risposta** approvato dalla direzione, con definizioni di gravità;\n- un **team** con ruoli chiari: *incident commander* (decide e coordina), analisti di sicurezza, amministratori IT, **comunicazione**, **legale/DPO**, rappresentante della direzione;\n- **playbook** per scenari ricorrenti (phishing, ransomware, account compromesso, data leak): passi, decisioni, responsabili;\n- **strumenti** pronti (log centralizzati, EDR, accessi di emergenza, contatti dei fornitori);\n- **canale di comunicazione alternativo** (out-of-band): se la posta o la chat aziendale sono compromesse, serve un modo diverso per coordinarsi;\n- **backup** testati e non raggiungibili dalla rete di produzione;\n- **esercitazioni** (tabletop): la squadra ripercorre a tavolino uno scenario simulato.\n\nUn piano mai provato non funziona: durante una crisi non si improvvisano contatti e responsabilità.` },
      { h: 'Rilevamento e analisi', b: `Qui si risponde a tre domande: **è un incidente vero?** **Quanto è grave?** **Qual è il perimetro?**\n\nSi parte dall’allarme (SIEM, EDR, segnalazione di un utente) e si fa **triage**: si raccolgono log e telemetria, si cerca di confermare, si stabilisce la gravità in base all’impatto su dati e servizi.\n\n- **Scoping**: quali host, account e dati sono coinvolti?\n- **Indicatori**: file, IP, domini, account usati dall’attore.\n- **Cronologia**: costruire una linea temporale, dal primo segno di compromissione in poi.\n- **Documentazione**: si annotano ora, azione, autore e motivo, fin dal primo istante.\n\nSi devono evitare due errori opposti: **sottovalutare** (si chiude un falso negativo grave) e **agire d’impulso** (spegnere un server cancellando prove volatili, o avvisare l’attaccante prima del contenimento).\n\nLa gravità decide chi coinvolgere: un solo PC con un malware noto è gestito dal SOC; la cifratura di un file server coinvolge la direzione.` },
      { h: 'Contenimento, eradicazione, recupero', b: `Sono tre fasi distinte.\n\n**Contenimento**: fermare la diffusione del danno. A breve termine: **isolare** l’host dalla rete (non spegnerlo, per non perdere la memoria), disabilitare account compromessi, bloccare IP e domini. A lungo termine: segmentazione temporanea, regole di accesso più strette. La scelta è un compromesso tra fermare l’attaccante e mantenere il servizio.\n\n**Eradicazione**: rimuovere la **causa**: malware, account creati dall’attore, meccanismi di persistenza, vulnerabilità sfruttata (patch). Non basta «ripulire»: se si lascia la vulnerabilità l’attaccante torna.\n\n**Recupero**: riportare i sistemi in produzione in modo sicuro: ripristino da **backup puliti** (verificati), ricostruzione di sistemi compromessi, **monitoraggio rafforzato** per scovare segni di ritorno, riattivazione graduale.\n\n> Ordine tipico: isolo → analizzo cosa è successo → rimuovo la causa → ripristino da backup noti e sicuri → osservo con attenzione.\n\nRipristinare prima di aver eradicato espone a una **nuova compromissione**.` },
      { h: 'Comunicazione e obblighi normativi', b: `Una risposta efficace è anche **comunicazione** controllata.\n\n- **Interna**: aggiornamenti regolari, canale riservato, principio del **need-to-know** (informa solo chi serve), un unico portavoce.\n- **Esterna**: clienti, fornitori, stampa, autorità. Un messaggio incoerente danneggia più dell’incidente.\n- **Legale e normativa**: in caso di violazione di dati personali, il **GDPR** richiede al titolare di notificare il Garante **entro 72 ore** da quando ne è venuto a conoscenza (se c’è rischio per le persone). La direttiva **NIS2** prevede per i soggetti coinvolti un preallarme entro **24 ore**, una notifica entro **72 ore** e una relazione finale entro un mese.\n- **Assicurazione e forze dell’ordine**: si contattano secondo il piano.\n\nBuone pratiche: fatti verificati e non supposizioni, nessuna attribuzione affrettata, nessuna promessa non mantenibile. Il responsabile della comunicazione lavora con il legale prima di rilasciare dichiarazioni.\n\nIl **DPO** (responsabile della protezione dei dati) va coinvolto presto quando sono toccati dati personali.` },
      { h: 'Conservare le prove', b: `Mentre si contiene e si ripristina non si deve **distruggere** ciò che serve a capire e, se necessario, a procedere in giudizio.\n\n- **Raccogli prima di cancellare**: copia di log, immagine della memoria dove possibile, immagini del disco dei sistemi chiave.\n- **Isola, non spegnere**: la memoria volatile contiene processi, connessioni e talvolta chiavi di cifratura.\n- **Hash** delle copie raccolte e **catena di custodia** (chi, quando, dove, con quale sigillo).\n- **Lavora su copie**, non sugli originali.\n- **Orari in UTC** e registro cronologico delle azioni svolte (inclusi i tuoi interventi).\n\nUn compromesso reale: il ripristino rapido può confliggere con la raccolta di prove. Il piano deve dire **chi decide** e con quali criteri. In molti casi si ripristina da backup su sistemi nuovi, conservando i sistemi compromessi per l’analisi.\n\nTutto ciò che si fa **cambia** lo stato dei sistemi: per questo conviene annotare ogni azione in modo che l’analisi successiva ne tenga conto.` },
      { h: 'Tabletop: ransomware, la linea temporale', b: `Scenario simulato (orari locali):\n\n> **08:10** Un’email con allegato arriva a un utente dell’amministrazione.\n> **08:14** L’utente apre l’allegato.\n> **08:20** L’EDR segnala un processo sospetto sul PC: allarme al SOC.\n> **08:45** Il SOC conferma e dichiara l’incidente; avvisa il responsabile.\n> **09:00** Il PC viene isolato dalla rete; l’account dell’utente è disabilitato.\n> **09:30** Dall’analisi dei log emergono altri 3 PC con lo stesso comportamento.\n> **10:15** Si disabilitano gli account compromessi e si cambiano le credenziali privilegiate.\n> **11:00** Il legale e il DPO sono informati; si valuta la notifica.\n> **12:00** Si avvia il ripristino da backup offline verificato.\n> **Giorno +3** Riunione di lezioni apprese.\n\n**Tempi**: dal primo allarme al contenimento (08:20 → 09:00) passano **40** minuti; dall’apertura dell’allegato all’allarme (08:14 → 08:20) **6** minuti; dall’arrivo dell’email al contenimento **50** minuti.\n\n**Fasi**: 08:20–08:45 = rilevamento e analisi; 09:00 e 10:15 = contenimento; 12:00 = recupero; giorno +3 = lezioni apprese.` },
      { h: 'Lezioni apprese e metriche', b: `Un incidente chiuso senza riflessione si ripete. La riunione di **lezioni apprese** (post-incident review) si fa entro pochi giorni, **senza cercare colpevoli** (blameless): si cercano cause e miglioramenti.\n\nDomande guida:\n\n- Che cosa è successo, in quale ordine, e perché?\n- Che cosa ha funzionato e che cosa no (rilevamento, comunicazione, strumenti)?\n- Quale causa radice ha permesso l’incidente (una patch mancante, un account debole, una regola assente)?\n- Quali azioni concrete, con **responsabile e scadenza**, ridurranno il rischio?\n\nMetriche utili:\n\n- **MTTD** (tempo medio di rilevamento): dall’inizio dell’attività al rilevamento;\n- **MTTR/MTTC** (tempo medio di risposta o contenimento);\n- numero di host compromessi, dati coinvolti, tempo di inattività.\n\nLe azioni confluiscono nella **preparazione**: nuove regole di rilevamento, playbook aggiornati, formazione, correzioni all’architettura. Così il ciclo si chiude e la prossima risposta parte da un livello più alto.` }
    ],
    exercises: [
      order('Ordina le fasi del ciclo di risposta agli incidenti', ['Preparazione', 'Rilevamento e analisi', 'Contenimento', 'Eradicazione', 'Recupero', 'Lezioni apprese'], 'Le sei fasi in ordine logico; il ciclo poi ricomincia dalla preparazione.'),
      order('Ordina cronologicamente le tappe del tabletop ransomware', ['08:14 allegato aperto', '08:20 allarme EDR', '08:45 incidente dichiarato', '09:00 PC isolato', '12:00 ripristino da backup'], 'Aprire l’allegato precede l’allarme, la dichiarazione, l’isolamento e il ripristino.'),
      fill('Nel tabletop, quanti minuti passano dal primo allarme (08:20) al contenimento (09:00)?', ['40', 'quaranta'], '09:00 − 08:20 = 40 minuti.'),
      fill('Entro quante ore il GDPR richiede di norma la notifica di una violazione di dati personali al Garante? (numero)', ['72'], 'Entro 72 ore da quando se ne ha conoscenza, se c’è rischio per le persone.'),
      mc('Un PC è sospetto di compromissione da ransomware. Qual è la prima azione di contenimento più appropriata?', ['Isolarlo dalla rete senza spegnerlo', 'Spegnerlo staccando la corrente e cancellare i file', 'Pagare subito il riscatto', 'Lasciarlo acceso e collegato per osservare'], 0, 'Isolare ferma la diffusione e conserva la memoria volatile.'),
      mc('Qual è la differenza tra contenimento ed eradicazione?', ['Il primo ferma la diffusione, la seconda rimuove la causa', 'Sono due nomi della stessa identica fase operativa', 'Il primo ripristina i dati, la seconda blocca gli utenti', 'La seconda avviene sempre prima della fase di rilevazione'], 0, 'Contenere = limitare il danno; eradicare = togliere malware, persistenza e vulnerabilità.'),
      mc('A che cosa serve un playbook?', ['A guidare passi, decisioni e responsabili per uno scenario ricorrente', 'A sostituire il SIEM', 'A scegliere il fornitore di antivirus', 'A documentare i bilanci aziendali'], 0, 'Nei momenti critici riduce le improvvisazioni.'),
      mc('Perché serve un canale di comunicazione alternativo (out-of-band)?', ['Perché posta e chat aziendali potrebbero essere compromesse', 'Perché è più veloce della posta', 'Perché è obbligatorio per legge in ogni caso', 'Perché evita di registrare le azioni'], 0, 'L’attaccante potrebbe leggere i canali ordinari.'),
      mc('Che cosa caratterizza una riunione di lezioni apprese ben condotta?', ['Ricerca delle cause e azioni con responsabile e scadenza, senza cercare colpevoli', 'Individuazione del colpevole da sanzionare', 'Chiusura rapida senza verbale', 'Discussione solo dei successi'], 0, 'Un approccio blameless favorisce segnalazioni oneste e miglioramenti reali.'),
      fill('Nel tabletop, da quanti PC in aggiunta al primo si è scoperto lo stesso comportamento sospetto (09:30)? (numero)', ['3', 'tre'], 'L’analisi dei log ha trovato altri 3 PC.')
    ],
    test: [
      fill('Dall’arrivo dell’email (08:10) al contenimento (09:00) passano quanti minuti?', ['50', 'cinquanta'], '09:00 − 08:10 = 50 minuti.'),
      mc('Quale fase comprende la scrittura di playbook e le esercitazioni?', ['Preparazione', 'Eradicazione', 'Recupero', 'Rilevamento e analisi'], 0, 'Tutto ciò che si fa prima dell’incidente rientra nella preparazione.'),
      mc('Perché si lavora su copie delle prove e non sugli originali?', ['Per non alterare l’originale e poterne dimostrare l’integrità', 'Per risparmiare spazio', 'Perché gli originali sono sempre cifrati', 'Per rendere l’analisi più lenta'], 0, 'L’originale va conservato intatto; si verifica con hash che la copia coincida.'),
      mc('Quale scelta rischia di far ritornare l’attaccante?', ['Ripristinare i sistemi senza aver chiuso la vulnerabilità sfruttata', 'Verificare i backup prima del ripristino', 'Cambiare le credenziali privilegiate', 'Monitorare con più attenzione dopo il recupero'], 0, 'Senza eradicazione la stessa porta resta aperta.'),
      fill('Nel tabletop, quanti minuti passano dall’apertura dell’allegato (08:14) all’allarme EDR (08:20)?', ['6', 'sei'], '08:20 − 08:14 = 6 minuti.'),
      mc('Che cosa misura l’MTTD?', ['Il tempo medio per rilevare un incidente', 'Il tempo medio di ripristino dei backup completi', 'Il numero di host compromessi', 'Il costo di un incidente'], 0, 'Mean Time To Detect: dall’inizio dell’attività al rilevamento.'),
      mc('Chi dovrebbe essere coinvolto presto quando l’incidente riguarda dati personali?', ['Il legale e il DPO', 'Solo il reparto marketing', 'Nessuno finché non è tutto risolto', 'Solo i fornitori'], 0, 'Servono per valutare gli obblighi di notifica e la comunicazione.')
    ]
  });

  /* ---------- 4 · Forense digitale ---------- */
  C.addTopic({
    id: 'cyb-forense-digitale', subject: 'cyb', stage: 'L4', minutes: 12, prereq: ['cyb-incident-response'],
    title: 'Forense digitale: prove, integrità e catena di custodia',
    summary: 'Ordine di volatilità, catena di custodia, acquisizione di disco, memoria e rete, hash, timeline, documentazione, ammissibilità e cloud.',
    objectives: ['Applicare l’ordine di volatilità nella raccolta delle prove', 'Spiegare hash, write blocker e catena di custodia per garantire l’integrità', 'Costruire e leggere una timeline e valutare i limiti della forense cloud'],
    pages: [
      { h: 'Scopo e principi', b: `La **digital forensics** acquisisce, conserva, analizza e documenta prove digitali in modo che i risultati siano **ripetibili** e verificabili da un terzo (un giudice, un perito della controparte).\n\nPrincipi guida:\n\n- **Non alterare** l’originale: ogni intervento diretto lo modifica;\n- **Lavorare su copie** verificate con hash;\n- **Documentare** ogni azione, strumento e versione;\n- **Competenza e metodo**: solo operazioni che si sa spiegare;\n- **Minimizzare** l’impatto sull’operatività e sui dati personali non pertinenti.\n\nLa forense serve in tre contesti: **risposta agli incidenti** (capire cosa è successo), **indagini interne** (violazioni delle policy) e **procedimenti legali**. Nel primo l’urgenza è il ripristino; negli altri conta di più la formalità. Il metodo ben fatto serve per entrambi.\n\nFasi classiche: **identificazione → conservazione → acquisizione → analisi → presentazione**.` },
      { h: 'Ordine di volatilità', b: `Le prove digitali **svaniscono** a velocità diverse. Si raccolgono dalla più volatile alla meno (principio dell’**RFC 3227**).\n\n1. **Registri e cache** della CPU (spesso non acquisibili in pratica);\n2. **Memoria RAM**, tabelle di rete (ARP, routing), processi in esecuzione, connessioni aperte;\n3. **File temporanei** e di swap;\n4. **Disco** (file system, registri locali);\n5. **Log remoti** e dati di monitoraggio (SIEM, firewall);\n6. **Configurazione fisica** e topologia di rete;\n7. **Supporti di archiviazione** e **backup**.\n\n> Spegnere un sistema acceso **perde** RAM, processi e connessioni attive: se possibile si acquisisce prima la memoria.\n\nIl principio dice di **non** seguire solo la comodità: copiare un disco è facile, ma se nel frattempo la connessione di rete aperta si chiude, quell’informazione è perduta.\n\nNella pratica si bilanciano volatilità, importanza della prova e rischio di alterarla. Ogni scelta va **annotata**.` },
      { h: 'Integrità: hash e write blocker', b: `Per dimostrare che una copia è identica all’originale si usa una **funzione di hash crittografica** (per esempio SHA-256). Produce un’impronta di lunghezza fissa: **64 caratteri esadecimali** per SHA-256 (32 per MD5, ormai debole).\n\nProprietà: stesso input → stesso hash; cambia **un solo bit** → l’hash è completamente diverso.\n\n> L’hash SHA-256 di un file vuoto è e3b0c442...b855 (valore noto).\n\nProcedura:\n\n1. calcolare l’hash dell’originale **prima** della copia;\n2. creare un’**immagine bit-a-bit** (include anche lo spazio non allocato, dove restano tracce di file cancellati);\n3. calcolare l’hash dell’immagine: **deve coincidere**;\n4. conservare l’originale sigillato e lavorare solo su copie (e verificare ancora l’hash all’inizio dell’analisi).\n\nIl **write blocker** (hardware o software) è un dispositivo posto tra il disco e il computer d’analisi: permette di **leggere** ma impedisce ogni **scrittura**, perché anche il semplice collegamento a un sistema operativo potrebbe modificare timestamp e metadati.` },
      { h: 'Catena di custodia', b: `La **catena di custodia** è il registro documentato di chi ha avuto la prova, quando, dove, per quale scopo e in che stato. Se ha una falla, la prova può essere contestata o esclusa.\n\nEstratto di un registro:\n\n> 14/10 09:00 UTC  Rossi  prelievo disco HDD-07 da SRV-DB1, sigillo n. 4471\n> 14/10 09:40 UTC  Rossi → Bianchi  consegna in laboratorio, sigillo 4471 integro\n> 14/10 11:15 UTC  Bianchi  immagine con write blocker, SHA-256 = 9f3a...\n> 14/10 11:20 UTC  Bianchi  verifica hash della copia = 9f3a... coincide\n> 15/10 08:00 UTC  Verdi  prelievo disco dall’armadio, senza motivo né firma di restituzione\n\n**Lettura**: le righe che riportano un valore hash sono **2**; tra il prelievo e la consegna passano **40** minuti; l’ultima riga è un **punto debole**: non indica scopo né restituzione, quindi si apre un buco nella catena.\n\nOgni passaggio riporta: identificativo dell’oggetto, descrizione, data e ora (UTC), persone coinvolte, motivo, condizione, sigillo. Si custodisce in luogo con **accesso controllato**.` },
      { h: 'Disco, memoria, rete: concetti', b: `**Disco**: l’immagine permette di esaminare file, metadati, cronologia dei browser, registri di sistema e **file cancellati** non ancora sovrascritti. Gli **artefatti** del sistema operativo (file recenti, esecuzioni di programmi, USB collegate) raccontano l’attività dell’utente.\n\n**Memoria**: l’acquisizione (dump) della RAM conserva processi attivi, connessioni, moduli caricati e talvolta chiavi o dati non cifrati. È **volatile**: va fatta presto e documentando lo strumento usato, perché l’acquisizione stessa altera la memoria in minima parte.\n\n**Rete**: le catture di pacchetti (PCAP) o i flussi (NetFlow) mostrano chi ha comunicato con chi, quanto e quando. Se il traffico è cifrato si vedono comunque metadati: indirizzi, porte, volumi, orari. Spesso i **log** di firewall, proxy e DNS bastano.\n\nPrincipio comune: le tre fonti si **integrano**. Una connessione vista in rete si associa al processo nella memoria e al file sul disco che lo ha avviato. Questo triangolare aumenta la certezza e permette di escludere spiegazioni alternative.` },
      { h: 'Timeline', b: `Una **timeline** dispone in ordine cronologico eventi provenienti da fonti diverse: file system, log di sistema, browser, rete. Mostra la **sequenza** e i legami di causa-effetto.\n\nI file system registrano diversi timestamp (spesso indicati come **MACB**): **M**odificato, **A**ccesso, **C**ambio dei metadati, **B**irth (creazione). I valori si possono alterare o cambiare in modo innocuo (copiare un file crea nuovi tempi), quindi si confermano con altre fonti.\n\nEsempio (tutto in UTC):\n\n> 10:15:02 creato il file fattura.docm nella cartella Download\n> 10:15:40 il file viene aperto dall’utente\n> 10:15:44 viene creato un nuovo file script nella cartella Temp\n> 10:16:01 prima connessione in uscita verso un dominio mai visto\n\nSe i quattro eventi vengono messi in ordine, la lettura è lineare: scaricato, aperto, qualcosa di nuovo creato, contatto esterno.\n\nBuone pratiche: **normalizzare** i fusi orari, segnalare gli **orologi sfasati**, distinguere i fatti dalle ipotesi e indicare per ogni voce la **fonte**.` },
      { h: 'Documentazione e ammissibilità', b: `Una prova vale se il metodo è **trasparente**. Il rapporto forense include:\n\n- scopo e quesiti dell’incarico;\n- elenco delle prove e catena di custodia;\n- strumenti usati (nome e versione) e hash di verifica;\n- passi eseguiti in modo **ripetibile**;\n- risultati distinti da **opinioni** e limiti noti;\n- allegati e firma dell’esaminatore.\n\n**Ammissibilità** (concetti generali): la prova deve essere **pertinente**, **autentica** e acquisita in modo **lecito**. Servono i presupposti giuridici (autorizzazione del titolare, rispetto dei diritti dei lavoratori e della privacy, mandato dove richiesto). In Italia la **Legge 48/2008**, che ha recepito la Convenzione di Budapest sul cybercrime, richiede di adottare misure che garantiscano la **conformità** della copia all’originale e la sua **immodificabilità**: da qui hash e immagini forensi.\n\nLe regole variano tra paesi e casi: nelle situazioni reali conviene coinvolgere sempre un legale e, se serve, un consulente tecnico qualificato.` },
      { h: 'Forense in cloud: i limiti', b: `Il cloud cambia le condizioni di lavoro.\n\n- **Modello di responsabilità condivisa**: non si ha accesso fisico all’hardware; si dipende dagli strumenti e dai log del provider.\n- **Risorse effimere**: contenitori e macchine virtuali possono sparire in pochi minuti insieme ai dati locali. Servono **snapshot** tempestivi e log inviati fuori.\n- **Multi-tenancy**: più clienti sullo stesso hardware, quindi non si possono acquisire dischi fisici condivisi.\n- **Log del provider**: attività delle API, accessi amministrativi, eventi di rete. Spesso hanno **retention limitata** e vanno abilitati in anticipo.\n- **Giurisdizione**: i dati possono stare in paesi diversi, con leggi differenti sull’accesso.\n- **Cooperazione del provider**: tempi e modalità dipendono dal contratto.\n\n> Esempio pratico: una macchina virtuale compromessa viene fermata, se ne fa uno **snapshot** del volume e si conservano i log di audit dell’account per la finestra interessata.\n\nIn sintesi: nel cloud la forense si **prepara prima** (logging attivo, retention adeguata, procedure concordate con il fornitore), perché dopo spesso è tardi.` }
    ],
    exercises: [
      order('Ordina le fonti dalla più volatile alla meno volatile', ['Registri e cache', 'Memoria RAM', 'File temporanei e swap', 'Disco', 'Log remoti', 'Backup e archivi'], 'Si raccoglie ciò che svanisce prima: dalla CPU e dalla RAM fino agli archivi.'),
      order('Ordina la timeline dell’esempio (dal più antico)', ['10:15:02 fattura.docm creato in Download', '10:15:40 file aperto', '10:15:44 nuovo script in Temp', '10:16:01 connessione in uscita'], 'Il file viene scaricato, aperto, poi compare il nuovo file e infine il contatto esterno.'),
      mc('Perché si usa un write blocker?', ['Per leggere il disco senza possibilità di scrivervi', 'Per cifrare il disco', 'Per cancellare i dati sensibili', 'Per velocizzare la copia'], 0, 'Anche solo il collegamento potrebbe alterare metadati: il blocco in scrittura protegge l’originale.'),
      fill('Quanti caratteri esadecimali ha un hash SHA-256? (numero)', ['64'], '256 bit / 4 bit per carattere = 64 caratteri.'),
      fill('Nell’estratto della catena di custodia, quante righe riportano un valore hash?', ['2', 'due'], 'Sono la riga dell’immagine (11:15) e quella della verifica (11:20).'),
      fill('Nello stesso estratto, quanti minuti passano tra il prelievo (09:00) e la consegna in laboratorio (09:40)?', ['40', 'quaranta'], '09:40 − 09:00 = 40 minuti.'),
      mc('Nell’estratto, quale riga indebolisce la catena di custodia?', ['Il prelievo del 15/10 senza motivo né firma di restituzione', 'La verifica hash dell’immagine', 'L’uso del write blocker', 'Il sigillo n. 4471 integro'], 0, 'Manca lo scopo e il documento di restituzione: nessuno può dire cosa è stato fatto al disco.'),
      mc('Un computer acceso è sospetto. Per l’ordine di volatilità, che cosa si acquisisce prima?', ['La memoria RAM', 'L’immagine del disco', 'I backup', 'La configurazione fisica'], 0, 'La RAM svanisce allo spegnimento: va acquisita per prima.'),
      mc('Perché nel cloud si dovrebbero abilitare i log e le procedure prima di un incidente?', ['Perché le risorse sono effimere e i log hanno retention limitata', 'Perché il cloud non produce log', 'Perché non esiste alcuna forense cloud', 'Perché i dischi fisici sono sempre accessibili'], 0, 'Dopo l’incidente istanze e log potrebbero non esistere più.'),
      mc('Che cosa succede all’hash se si modifica un solo bit del file?', ['Cambia completamente', 'Non cambia', 'Cambia solo l’ultimo carattere', 'Diventa vuoto'], 0, 'L’effetto valanga: anche un bit modifica l’intero hash.')
    ],
    test: [
      mc('Che cosa dimostra l’uguaglianza degli hash di originale e immagine?', ['Che la copia è identica all’originale', 'Che il disco non contiene alcun malware attivo', 'Che il proprietario è innocente', 'Che i file non sono stati cancellati dopo il sequestro'], 0, 'È una verifica di integrità della copia, non un giudizio sul contenuto.'),
      mc('Quale elemento NON fa parte di una buona voce di catena di custodia?', ['Un’opinione sulla colpevolezza dell’utente', 'Data e ora in UTC', 'Persone coinvolte', 'Numero del sigillo'], 0, 'La catena registra fatti e movimenti, non giudizi.'),
      fill('Nell’estratto di timeline della lezione, quanti secondi passano tra la creazione di fattura.docm (10:15:02) e l’apertura (10:15:40)?', ['38', 'trentotto'], '40 − 2 = 38 secondi.'),
      mc('Che cosa significa la «B» di MACB?', ['Birth, cioè creazione', 'Backup', 'Blocco', 'Binario'], 0, 'Birth time: il momento di creazione del file.'),
      mc('Perché l’immagine bit-a-bit è preferibile a una semplice copia dei file?', ['Include anche lo spazio non allocato con tracce di file cancellati', 'Occupa meno spazio', 'Non richiede hash', 'Modifica i timestamp in modo utile'], 0, 'Una copia dei file visibili perde le tracce nei settori non allocati.'),
      mc('Quale caratteristica del cloud rende la raccolta delle prove più difficile?', ['Le istanze effimere e l’assenza di accesso fisico all’hardware', 'La disponibilità di troppi dischi fisici', 'L’assenza di rete', 'L’obbligo di spegnere i server'], 0, 'Dati e macchine possono scomparire; ci si affida ai log e agli snapshot del provider.'),
      fill('Qual è il termine italiano per «chain of custody»? (due parole: catena di ...)', ['catena di custodia', 'custodia'], 'La catena di custodia documenta ogni passaggio della prova.')
    ]
  });

  /* ---------- 5 · Analisi statica malware: concetti ---------- */
  C.addTopic({
    id: 'cyb-analisi-statica-malware-concetti', subject: 'cyb', stage: 'L4', minutes: 12, prereq: ['cyb-forense-digitale'],
    title: 'Analisi statica del malware: concetti per difensori',
    summary: 'Ambiente sicuro, hash e reputazione, stringhe, header PE e import, sandbox, indicatori e comportamenti, YARA: solo a livello concettuale.',
    objectives: ['Descrivere un ambiente di analisi sicuro e il flusso di triage di un campione', 'Interpretare hash, stringhe, import e sandbox a livello concettuale', 'Distinguere indicatori di compromissione da comportamenti e spiegare l’idea delle regole YARA'],
    pages: [
      { h: 'Perché si analizza e come', b: `L’analisi di un campione sospetto serve a rispondere a domande difensive: **che cosa fa**, **come si riconosce**, **come ci si è arrivati**, **come si contiene e si rileva**. Non serve a replicare o modificare il codice.\n\nDue approcci complementari:\n\n- **Statica**: si studia il file **senza eseguirlo** (hash, stringhe, struttura, import, risorse);\n- **Dinamica**: si osserva il campione eseguito **in un ambiente controllato** (sandbox) e si registra il comportamento.\n\nL’analisi statica è più sicura e veloce per il triage, ma ha limiti: file **offuscati o compressi** nascondono il contenuto, e una stringa non prova da sola l’uso.\n\nLa regola d’oro è la **prudenza**: un campione è potenzialmente pericoloso, quindi non si apre mai su una postazione di lavoro normale e non si carica su servizi pubblici se contiene **dati riservati** dell’organizzazione.\n\nIn questa lezione si parla solo di concetti difensivi: nessun codice dannoso, nessun metodo di aggiramento.` },
      { h: 'Ambiente di analisi sicuro', b: `Un laboratorio per l’analisi deve **contenere** il rischio.\n\n- **Macchina virtuale dedicata**, con **snapshot** pulito a cui tornare dopo ogni sessione;\n- **Rete isolata**: nessun accesso alla rete aziendale; se serve una rete, solo simulata o a forte filtraggio;\n- **Nessuna cartella condivisa** o appunti condivisi con il sistema ospite, nessun account o credenziale reali nella VM;\n- **Campioni conservati inerti**, per esempio in archivio protetto con nome file che non ne consenta l’apertura accidentale (si «disinnesca» l’estensione);\n- **Strumenti aggiornati** e ospite separato dal resto, con sistema operativo patchato;\n- **Accesso limitato** e registro di chi analizza cosa.\n\n> Esempio di regola: il campione entra nel laboratorio solo tramite un percorso unidirezionale e non esce mai senza essere neutralizzato.\n\nSi tiene presente che alcuni campioni **rilevano** di essere in una VM e si comportano in modo diverso: non vedere un’attività in sandbox non prova che il file sia innocuo.\n\nAnche l’**igiene personale** conta: non aprire mai allegati sospetti fuori dal laboratorio e segnalare subito al SOC.` },
      { h: 'Hash e ricerche di reputazione', b: `Il primo passo è calcolare l’**hash** del file (SHA-256) e cercarlo in archivi di **reputazione**.\n\n- Un hash identifica **quel file esatto**. Se è già noto, si recupera subito l’etichetta di minaccia, la famiglia e le note di altri analisti.\n- Se non è noto, **non significa che sia sicuro**: può essere un campione nuovo o ricompilato.\n\n> Hash SHA-256 di un file vuoto: e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855 (utile come esempio di riferimento: indica «nessun contenuto»).\n\nBuone pratiche:\n\n- cercare **l’hash**, non caricare il file: un upload pubblico può **divulgare** documenti riservati o avvisare chi lo ha creato;\n- dare peso ai **punteggi di più motori** e leggerne le etichette con senso critico: un solo motore che segnala può essere un falso positivo;\n- registrare data e fonte della ricerca, perché la reputazione **cambia** nel tempo.\n\nL’hash è un indicatore **fragile**: basta ricompilare o cambiare un byte per ottenerne uno nuovo (vedi la piramide del dolore nell’ultima lezione).\n\nPer questo l’hash è l’inizio, mai la conclusione.` },
      { h: 'Stringhe, header e import', b: `Esaminando un eseguibile Windows (formato **PE**, Portable Executable) si possono ottenere indizi senza eseguirlo.\n\n- **Stringhe**: testo leggibile (URL, nomi di file, messaggi). Possono rivelare scopo e infrastruttura; mancano se sono offuscate.\n- **Header PE**: inizia con la firma «MZ»; elenca le **sezioni** (.text per il codice, .data, .rsrc), l’architettura e un **timestamp di compilazione** (modificabile, quindi non è una prova).\n- **Import**: le funzioni di sistema che il programma richiede alle librerie. Indicano le **capacità** possibili: lavorare con file, registro, rete, crittografia.\n- **Entropia** delle sezioni (0–8): valori vicini a 8 suggeriscono dati **compressi o cifrati**, spesso segno che il contenuto è nascosto.\n\nEsempio di report:\n\n> Imports: CreateFileW, WriteFile, RegSetValueExW, InternetOpenUrlW, CryptEncrypt\n> Strings: «Your files», «bitcoin», «.locked»\n> Entropia sezione .data: 7,9 / 8\n\nLettura: **5** funzioni importate che coprono file, registro, rete e crittografia; entropia **alta**; stringhe da richiesta di riscatto. L’insieme è compatibile con un **ransomware**, ma resta un’**ipotesi** da confermare in sandbox: ogni singolo elemento è presente anche in software legittimo.` },
      { h: 'Sandbox e analisi dinamica', b: `Una **sandbox** esegue il campione in un ambiente isolato e **registra** cosa accade, così l’analista legge un rapporto invece di osservare a mano.\n\nCosa si osserva di solito:\n\n- **File**: creati, modificati, cancellati;\n- **Registro e persistenza**: modifiche che permettono di ripartire all’avvio;\n- **Processi**: avviati, iniettati, relazione padre-figlio;\n- **Rete**: query DNS, connessioni, protocolli, destinazioni;\n- **Screenshot e comportamento** in generale.\n\nSandbox pubbliche e commerciali producono rapporti con **punteggio** e mappatura delle tecniche. Vantaggi: velocità, scala. Limiti:\n\n- il campione può **attendere** o verificare l’ambiente prima di agire;\n- può richiedere un **input** (un clic, un documento aperto);\n- una sandbox non mostra tutto il possibile comportamento, ma solo **quello eseguito**.\n\n> Rapporto: DNS query verso update-check.example.test; creazione di decine di file con estensione .locked; modifica di una chiave di avvio automatico.\n\nQuesti tre fatti sono **comportamenti**: si traducono in rilevamenti sull’infrastruttura (blocco del dominio) e sugli endpoint (alert su creazione massiva di file e chiavi di avvio).` },
      { h: 'Indicatori e comportamenti', b: `Dall’analisi nascono due tipi di risultato.\n\n**IOC** (Indicators of Compromise): elementi **osservabili** che segnalano una compromissione: hash, indirizzi IP, domini, URL, nomi di file, chiavi di registro, mutex. Sono facili da usare (blocco, ricerca nei log) ma hanno **breve durata**: l’attore li cambia.\n\n**Comportamenti** (TTP, tattiche, tecniche e procedure): ciò che l’attore **fa**: cifrare molti file, cancellare copie di ripristino, avviare una shell da un documento. Sono più difficili da cambiare e quindi più **durevoli**.\n\n> IOC: dominio update-check.example.test\n> Comportamento: un processo scrive in pochi secondi centinaia di file e li rinomina con una nuova estensione.\n\nIn pratica si usano entrambi: gli **IOC** per chiudere subito l’incidente noto (ricerca retroattiva nei log, blocchi); i **comportamenti** per costruire rilevamenti che reggano alle nuove varianti.\n\nOgni IOC va accompagnato da **contesto**: fonte, data, affidabilità, scadenza. Un indicatore senza contesto produce falsi positivi, e un IP condiviso oggi malevolo può essere domani un servizio legittimo.` },
      { h: 'YARA: l’idea delle regole sui file', b: `**YARA** è uno strumento per descrivere **famiglie di file** tramite regole di pattern. Si usa per cercare, in archivi di file o in memoria, ciò che ha caratteristiche note: stringhe, sequenze di byte, struttura.\n\nUna regola ha tre parti: **metadati**, **strings** (i pattern) e **condition** (come combinarli). Esempio concettuale e innocuo:\n\n> rule Documento_Macro_Sospetta\n> {\n>   strings: $a = "AutoOpen"  $b = "Shell"\n>   condition: $a and $b\n> }\n\nLa regola scatta sui file che contengono **entrambe** le stringhe. Può dare falsi positivi (un documento legittimo con macro interne) e falsi negativi (le stringhe sono offuscate): per questo si combinano **più indizi** e si testa la regola su un insieme di file **legittimi** oltre che su campioni noti.\n\nBuone regole: specifiche (non una sola stringa generica), documentate, versionate e provate.\n\nFlusso completo del triage: **hash e reputazione → analisi statica → sandbox → estrazione di IOC e comportamenti → regole e blocchi → condivisione**. Il fine è **rilevare e difendersi**, non riprodurre o aggirare le protezioni di altri.` }
    ],
    exercises: [
      order('Ordina il flusso di triage di un campione', ['Hash e reputazione', 'Analisi statica', 'Sandbox', 'Estrazione di IOC', 'Regole e blocchi'], 'Dal controllo meno invasivo (hash) fino ai rilevamenti da distribuire.'),
      fill('Nel report della lezione (CreateFileW, WriteFile, RegSetValueExW, InternetOpenUrlW, CryptEncrypt) quante funzioni sono importate?', ['5', 'cinque'], 'Sono cinque nomi di funzione.'),
      mc('Perché un’entropia di 7,9 su 8 in una sezione è un indizio?', ['Suggerisce dati compressi o cifrati', 'Prova che il file è sicuro', 'Indica un file vuoto', 'Indica che il file è in testo semplice'], 0, 'Dati molto casuali sono tipici di compressione o cifratura: spesso nascondono il contenuto.'),
      mc('Un hash sconosciuto nei database di reputazione significa che il file è:', ['Non necessariamente sicuro: potrebbe essere nuovo o ricompilato', 'Sicuro', 'Sicuramente dannoso', 'Cifrato'], 0, 'L’assenza di un riscontro non è un’assoluzione.'),
      mc('Quale precauzione è corretta prima di analizzare un campione?', ['Usare una VM isolata con snapshot e nessuna cartella condivisa', 'Aprirlo sul PC di lavoro per vedere cosa succede', 'Collegare la VM alla rete aziendale', 'Caricare in chiaro tutti i documenti riservati su un servizio pubblico'], 0, 'L’isolamento e la possibilità di ripristino riducono il rischio.'),
      mc('Quale tra questi è un comportamento (e non un IOC)?', ['Un processo che cifra centinaia di file in pochi secondi', 'Il dominio update-check.example.test', 'L’hash SHA-256 del file', 'L’indirizzo IP di un server'], 0, 'Descrive ciò che il malware fa; gli altri sono indicatori osservabili puntuali.'),
      fill('Qual è la firma iniziale (magic) degli eseguibili PE? (due lettere)', ['MZ', 'mz'], 'L’header DOS inizia con «MZ».'),
      mc('Perché non caricare su un servizio pubblico un file che potrebbe contenere dati riservati?', ['Potrebbe divulgare informazioni e avvisare l’autore', 'Perché i servizi pubblici non analizzano mai i file caricati', 'Perché il caricamento fa perdere il valore dell’hash', 'Perché è sempre vietato dalla legge in ogni caso'], 0, 'Meglio cercare l’hash o usare un ambiente interno.'),
      mc('Nel report della sandbox viene registrata una query DNS verso un dominio mai visto. Quale azione difensiva è sensata?', ['Cercare quel dominio nei log e valutarne il blocco', 'Ignorarla perché è solo DNS', 'Spegnere tutto il DNS aziendale', 'Contattare il dominio'], 0, 'Un dominio è un IOC utile per la ricerca retroattiva e il blocco.'),
      mc('Che cosa descrive la parte condition di una regola YARA?', ['Come combinare le stringhe per far scattare la regola', 'Chi ha scritto la regola', 'Il nome del file da analizzare', 'La versione del sistema operativo'], 0, 'Le strings definiscono i pattern, la condition la logica di combinazione.')
    ],
    test: [
      mc('Qual è un limite dell’analisi dinamica in sandbox?', ['Il campione può non mostrare tutto il suo comportamento in quell’esecuzione', 'Non registra la rete', 'È sempre più lenta di quella manuale', 'Richiede l’esecuzione sul PC di lavoro'], 0, 'Si osserva solo ciò che viene eseguito, e alcuni campioni controllano l’ambiente.'),
      fill('Quanti caratteri esadecimali ha l’hash SHA-256 di un file vuoto? (numero)', ['64'], 'Ogni SHA-256 ha 64 caratteri esadecimali.'),
      mc('Perché gli hash sono IOC fragili?', ['Basta cambiare un byte per ottenere un hash diverso', 'Sono troppo lunghi', 'Non si possono registrare', 'Si trovano solo in rete'], 0, 'Un attore può ricompilare o modificare il file senza fatica.'),
      mc('Un timestamp di compilazione in un header PE è:', ['Utile ma modificabile, quindi non prova', 'Sempre autentico', 'Sempre falso', 'Impossibile da leggere'], 0, 'Chi crea il file può impostare qualsiasi valore.'),
      mc('Una regola YARA basata su una sola stringa molto comune produrrà probabilmente:', ['Molti falsi positivi', 'Nessun allarme', 'Solo veri positivi', 'Un blocco della rete'], 0, 'Specificità e test su file legittimi sono essenziali.'),
      mc('Perché ogni IOC va accompagnato da contesto e scadenza?', ['Perché l’infrastruttura cambia e un indicatore vecchio genera falsi positivi', 'Perché lo richiede il formato PE', 'Perché ne aumenta la dimensione', 'Perché gli IOC non si possono cercare nei log'], 0, 'Un IP o un dominio può passare in mano a utenti legittimi.'),
      mc('Quale azione NON appartiene a un’analisi difensiva?', ['Modificare il campione per renderlo non rilevabile', 'Calcolare l’hash', 'Estrarre IOC', 'Scrivere una regola di rilevamento'], 0, 'L’obiettivo è rilevare e difendere, non aggirare le protezioni.')
    ]
  });

  /* ---------- 6 · Threat intelligence e ATT&CK ---------- */
  C.addTopic({
    id: 'cyb-threat-intelligence-e-attck', subject: 'cyb', stage: 'L4', minutes: 12, prereq: ['cyb-analisi-statica-malware-concetti'],
    title: 'Threat intelligence, Kill Chain e MITRE ATT&CK',
    summary: 'Tipi di intelligence, Cyber Kill Chain, ATT&CK, mappatura dei rilevamenti, vita degli IOC, STIX/TAXII, condivisione e piramide del dolore.',
    objectives: ['Distinguere i quattro livelli di threat intelligence e il loro uso', 'Usare Kill Chain e MITRE ATT&CK per descrivere un attacco e mappare i rilevamenti', 'Valutare la durata degli IOC con la piramide del dolore e conoscere STIX/TAXII e la condivisione'],
    pages: [
      { h: 'Che cos’è la threat intelligence', b: `La **Cyber Threat Intelligence (CTI)** è informazione sulle minacce **analizzata e contestualizzata**, utile per decidere. Un elenco di indirizzi IP è un dato; la CTI spiega *chi*, *perché*, *come* e *che cosa cambia per noi*.\n\nIl ciclo di vita dell’intelligence:\n\n1. **Requisiti**: quali domande servono (quali attori colpiscono il nostro settore?);\n2. **Raccolta** da fonti interne (incidenti, log) ed esterne (feed, comunità, report);\n3. **Elaborazione** e normalizzazione;\n4. **Analisi** (valutare affidabilità e rilevanza);\n5. **Diffusione** al destinatario giusto, nel formato giusto;\n6. **Feedback**: è stata utile? Si rivedono i requisiti.\n\nL’intelligence è utile solo se **cambia una decisione**: bloccare, rilevare, investire, formare. Un feed enorme senza analisi aumenta il rumore e i falsi positivi.\n\nLa valutazione delle fonti considera **affidabilità** della fonte e **credibilità** dell’informazione: dichiararle insieme evita di trattare una voce non verificata come un fatto.` },
      { h: 'Quattro livelli di CTI', b: `La CTI si distingue per **destinatario** e orizzonte temporale.\n\n- **Strategica**: per dirigenti e consiglio. Tendenze, motivazioni degli attori, rischi per settore e geografia; aiuta a decidere investimenti e priorità. Orizzonte: mesi o anni, linguaggio non tecnico.\n- **Operativa**: per responsabili di sicurezza e IR. Campagne in corso, intenzioni e tempi di un attore, come opera. Risponde a «sta per succedere a noi?».\n- **Tattica**: per SOC e detection engineer. **TTP**, cioè tecniche e procedure, utili per scrivere rilevamenti e organizzare caccia alle minacce.\n- **Tecnica (indicatori)**: per sistemi automatizzati. IOC puntuali come hash, IP, domini, URL; vita breve, uso immediato in blocchi e ricerche.\n\n> Esempio: «Il settore sanitario è bersaglio di ransomware» (strategica) → «un gruppo sta inviando email con allegati compressi questa settimana» (operativa) → «usa un documento che avvia una shell» (tattica) → «dominio update-check.example.test» (tecnica).\n\nProcedendo verso il basso, aumenta la **precisione** ma diminuisce la **durata**.` },
      { h: 'Cyber Kill Chain', b: `La **Cyber Kill Chain** di Lockheed Martin descrive un attacco come sequenza di **7 fasi**. Idea difensiva: interrompere la catena **in qualunque punto** la rende fallimentare.\n\n1. **Reconnaissance** (ricognizione): raccolta di informazioni sul bersaglio;\n2. **Weaponization**: preparazione del mezzo di attacco;\n3. **Delivery**: consegna (email, sito, supporto);\n4. **Exploitation**: sfruttamento di una debolezza o di un errore umano;\n5. **Installation**: installazione di un accesso persistente;\n6. **Command & Control (C2)**: canale di comando verso l’esterno;\n7. **Actions on Objectives**: raggiungimento dello scopo (furto, cifratura, sabotaggio).\n\nPer ogni fase si può associare una difesa: **detect, deny, disrupt, degrade, deceive**.\n\n> Esempio: filtro anti-phishing (Delivery: deny); blocco dei domini di C2 (C2: disrupt); segmentazione (Actions: degrade).\n\nLimiti: il modello è lineare e centrato sull’intrusione dall’esterno; non descrive bene le minacce interne, i movimenti laterali ripetuti o gli attacchi alla supply chain. Per questo si affianca ad ATT&CK.` },
      { h: 'MITRE ATT&CK: tattiche e tecniche', b: `**MITRE ATT&CK** è una base di conoscenza, pubblica e basata su osservazioni reali, di **tattiche** e **tecniche** usate dagli attori. Non è una checklist né una classifica.\n\n- **Tattica** = l’**obiettivo** a breve termine (il *perché*).\n- **Tecnica** = il **modo** in cui lo si raggiunge (il *come*). Ha un ID (es. **T1566**) e può avere **sotto-tecniche** (es. T1059.001).\n- **Procedura** = l’implementazione concreta di un gruppo.\n\nLa matrice **Enterprise** ha **14 tattiche**: Reconnaissance, Resource Development, Initial Access, Execution, Persistence, Privilege Escalation, Defense Evasion, Credential Access, Discovery, Lateral Movement, Collection, Command and Control, Exfiltration, Impact.\n\nTecniche citate in questa lezione:\n\n- **T1566** Phishing (Initial Access)\n- **T1059.001** PowerShell (Execution)\n- **T1110** Brute Force (Credential Access)\n- **T1078** Valid Accounts (varie tattiche)\n- **T1021** Remote Services (Lateral Movement)\n- **T1486** Data Encrypted for Impact (Impact)\n\nUsi difensivi: linguaggio comune, analisi delle lacune, rilevamenti, esercitazioni, report.` },
      { h: 'Mappare i rilevamenti su ATT&CK', b: `Associare ogni regola di rilevamento alla **tecnica** che intercetta fa emergere la **copertura** e le **lacune**.\n\nEsempio:\n\n> Regola «5 login falliti + successo dallo stesso IP» → **T1110** Brute Force (Credential Access)\n> Regola «Office avvia powershell» → **T1059.001** (Execution), spesso dopo **T1566**\n> Regola «cifratura massiva di file» → **T1486** (Impact)\n> Canary account usato → rilevamento di Discovery / Credential Access\n\nIn una mappa a colori si segnano le tecniche coperte: i vuoti guidano le priorità. Alcune attenzioni:\n\n- «**coperta**» non significa «rilevata sempre»: una tecnica ha molte varianti, e una regola ne copre una parte;\n- contare le regole non è un obiettivo: conta la **qualità** (test con attività simulata e autorizzata);\n- si privilegiano le tecniche **più frequenti** nel proprio settore (la CTI tattica indica quali).\n\nEsercizio di lettura: osservazioni → tattiche. «Allegato in email» = Initial Access; «avvio di powershell» = Execution; «nuovo servizio all’avvio» = Persistence; «cifratura dei file» = **Impact**; «invio di dati a un server esterno» = Exfiltration.` },
      { h: 'IOC e piramide del dolore', b: `Non tutti gli indicatori valgono uguale. La **piramide del dolore** (David Bianco) ordina i tipi di indicatore secondo quanto **costa** all’attaccante cambiarli (dal basso verso l’alto):\n\n1. **Valori hash**: banale (basta modificare il file);\n2. **Indirizzi IP**: facile;\n3. **Nomi di dominio**: semplice;\n4. **Artefatti di rete e host**: fastidioso;\n5. **Strumenti**: impegnativo;\n6. **TTP**: molto difficile, perché cambia il modo di operare.\n\nPiù si sale, più il rilevamento è **robusto** ma **più difficile** da costruire. Un rilevamento sui TTP mette in difficoltà l’avversario, un blocco di hash lo disturba per un minuto.\n\n**Durata di vita (shelf life)**: gli hash e gli IP scadono presto (ore o giorni, specie con infrastrutture condivise o cloud); i domini durano un po’ di più; i TTP durano anni.\n\n> Un indicatore valido dal 14/10 al 21/10 ha una finestra di **7 giorni**: oltre quella data va riverificato o rimosso, altrimenti produce falsi positivi.` },
      { h: 'STIX e TAXII', b: `Per scambiare intelligence in modo **automatizzabile** servono formati comuni.\n\n- **STIX** (Structured Threat Information eXpression): linguaggio, in JSON, per descrivere oggetti come *indicator*, *malware*, *threat-actor*, *attack-pattern* (le tecniche ATT&CK), *campaign*, *identity*, uniti da **relazioni** (*uses*, *indicates*, *targets*).\n- **TAXII** (Trusted Automated eXchange of Intelligence Information): protocollo su **HTTPS** per **trasportare** gli oggetti STIX tra server e client, tramite raccolte (*collections*).\n\nEsempio concettuale di indicatore STIX:\n\n> type: indicator\n> pattern: [domain-name:value = 'update-check.example.test']\n> valid_from: 2026-10-14T09:00:00Z\n> valid_until: 2026-10-21T09:00:00Z\n\nCampi come **valid_from / valid_until** formalizzano la durata; **confidence** e riferimenti alla fonte ne indicano l’affidabilità. STIX descrive il **contenuto**, TAXII il **trasporto**.\n\nVantaggio: un SIEM o una piattaforma di intelligence (per esempio **MISP**) importa automaticamente indicatori e relazioni, senza copiare a mano elenchi di valori.` },
      { h: 'Condividere: comunità e TLP', b: `Nessuna organizzazione vede tutto: **condividere** intelligence aumenta il costo per l’attaccante, che spesso riusa strumenti e infrastrutture su più vittime.\n\nFonti e comunità:\n\n- **ISAC/ISAO** di settore (finanza, sanità, energia…);\n- **CSIRT** nazionali (in Italia lo CSIRT Italia presso l’Agenzia per la Cybersicurezza Nazionale);\n- piattaforme collaborative come **MISP**;\n- fornitori commerciali e report pubblici.\n\nLa condivisione è regolata dal **TLP** (Traffic Light Protocol):\n\n- **TLP:CLEAR** diffusione libera;\n- **TLP:GREEN** alla comunità, non al pubblico;\n- **TLP:AMBER** solo all’interno dell’organizzazione e ai clienti che ne hanno bisogno;\n- **TLP:AMBER+STRICT** solo all’interno dell’organizzazione;\n- **TLP:RED** solo ai destinatari nominati.\n\nBuone pratiche: **rimuovere dati personali e sensibili**, indicare contesto e scadenza, rispettare l’etichetta TLP, dare **feedback** sull’utilità. Condividere non significa pubblicare i propri log: significa fornire indicatori e comportamenti **anonimizzati**, utili agli altri.` }
    ],
    exercises: [
      order('Ordina le fasi della Cyber Kill Chain', ['Reconnaissance', 'Weaponization', 'Delivery', 'Exploitation', 'Installation', 'Command and Control', 'Actions on Objectives'], 'Le sette fasi nell’ordine in cui un attacco le attraversa.'),
      order('Ordina la piramide del dolore dal più facile al più difficile da cambiare per l’attaccante', ['Hash', 'Indirizzi IP', 'Domini', 'Artefatti', 'Strumenti', 'TTP'], 'Dalla base (hash) al vertice (TTP).'),
      fill('Quante sono le tattiche della matrice ATT&CK Enterprise (come indicato nella lezione)? (numero)', ['14', 'quattordici'], 'Da Reconnaissance a Impact: 14 tattiche.'),
      fill('Quante sono le fasi della Cyber Kill Chain? (numero)', ['7', 'sette'], 'Da ricognizione ad azioni sugli obiettivi: 7 fasi.'),
      mc('A quale tattica ATT&CK appartiene la tecnica T1486 (Data Encrypted for Impact)?', ['Impact', 'Initial Access', 'Discovery', 'Persistence'], 0, 'Cifrare i dati per bloccarne l’uso è un effetto di impatto sulla disponibilità.'),
      fill('Un indicatore STIX è valido dal 14/10 al 21/10. Per quanti giorni vale?', ['7', 'sette'], '21 − 14 = 7 giorni.'),
      mc('Quale tipo di CTI serve soprattutto a SOC e detection engineer per scrivere rilevamenti?', ['Tattica (TTP)', 'Strategica', 'Solo tecnica (hash)', 'Nessuna'], 0, 'Le TTP descrivono come opera l’attore e si traducono in regole.'),
      mc('Quale coppia è corretta?', ['STIX descrive il contenuto, TAXII lo trasporta', 'TAXII descrive il contenuto, STIX lo trasporta', 'Sono due nomi dello stesso formato', 'STIX è un database di vulnerabilità'], 0, 'STIX = formato (JSON), TAXII = protocollo su HTTPS.'),
      mc('Una regola che rileva cinque login falliti seguiti da un successo si associa a:', ['T1110 Brute Force (Credential Access)', 'T1486 (Impact)', 'T1021 (Lateral Movement)', 'T1566 (Initial Access)'], 0, 'È il comportamento tipico di una forzatura di password.'),
      mc('Perché un rilevamento sui TTP è più robusto di un blocco su hash?', ['Cambiare il modo di operare è molto più costoso per l’attaccante', 'Perché gli hash non esistono più', 'Perché i TTP non vanno mai testati', 'Perché richiede meno dati'], 0, 'È il principio della piramide del dolore: più in alto, più «dolore».')
    ],
    test: [
      mc('Quale livello di CTI è pensato per la direzione e il consiglio di amministrazione?', ['Strategica', 'Tecnica', 'Tattica', 'Operativa'], 0, 'Serve a decidere investimenti e priorità, con linguaggio non tecnico.'),
      mc('Qual è la tattica ATT&CK che indica l’invio di dati verso un server esterno?', ['Exfiltration', 'Persistence', 'Reconnaissance', 'Execution'], 0, 'Exfiltration = sottrazione di dati dall’ambiente.'),
      mc('Secondo la lezione, quale indicatore ha in genere la durata più breve?', ['Un hash o un indirizzo IP', 'Una TTP di un gruppo', 'Una tecnica ATT&CK documentata', 'Un obiettivo strategico'], 0, 'Sono i più semplici da cambiare per l’attaccante.'),
      mc('TLP:AMBER+STRICT significa che l’informazione può essere condivisa:', ['Solo all’interno dell’organizzazione', 'Con il pubblico e con i media', 'Con tutta la comunità di settore interessata', 'Solo con le autorità giudiziarie competenti'], 0, 'È la restrizione più stretta della famiglia AMBER.'),
      mc('Una regola «Office avvia PowerShell» ricade in quale tattica?', ['Execution', 'Impact', 'Exfiltration', 'Discovery'], 0, 'T1059.001 PowerShell è una tecnica di esecuzione.'),
      fill('Come si chiama il modello a 7 fasi di Lockheed Martin? (inglese, tre parole: Cyber ... Chain)', ['cyber kill chain', 'kill chain'], 'Cyber Kill Chain.'),
      mc('Che cosa significa «una tecnica è coperta» in una mappa ATT&CK?', ['Esiste almeno una regola, che può coprire solo alcune varianti', 'È rilevata al 100% sempre', 'Non è mai stata usata', 'È bloccata dal firewall'], 0, 'Copertura non equivale a garanzia: contano varianti e qualità della regola.'),
      mc('Quale pratica è corretta nella condivisione di intelligence?', ['Rimuovere dati personali e rispettare l’etichetta TLP', 'Pubblicare i log interni completi', 'Ignorare la scadenza degli indicatori', 'Condividere solo senza contesto'], 0, 'Si condividono indicatori e comportamenti anonimizzati, con contesto e limiti d’uso.')
    ]
  });
})(window.ST = window.ST || {});
